    /**
     * Sloupce, které se zkopírují, ale obsahují tajemství nebo odkazují na
     * odchozí integraci — po pseudonymizaci se integrace vypnou, aby kopie
     * nikam nic neposlala (banka, e-mail, ISDS, e-shop).
     *
     * @var list<string>
     */
    public const POST_SQL = [
        'UPDATE bank_connections SET enabled = 0',
        'UPDATE bank_email_imap_settings SET enabled = 0',
        'UPDATE email_profiles SET is_active = 0',
        "UPDATE integration_connections SET status = 'paused' WHERE status = 'active'",
        'UPDATE submission_channel_credentials SET inbox_polling_enabled = 0',
        'UPDATE isds_gateway_registrations SET is_active = 0',
        'UPDATE mcp_server_settings SET enabled = 0',
        'UPDATE users SET totp_enabled = 0',
    ];

    /**
     * Veřejné účty institucí a platebních bran — zůstávají, aby aplikace
     * dál rozpoznala platby finančnímu úřadu, ČSSZ či výplaty brány.
     * Účty institucí ve mzdách jsou šifrované; dešifruje je služba.
     *
     * @var list<string> SELECT vracející sloupec `account`
     */
    public const PRESERVED_ACCOUNT_SQL = [
        "SELECT CONCAT(IF(COALESCE(account_prefix, '') = '', '', CONCAT(account_prefix, '-')), account_number, '/', bank_code) AS account FROM remittance_map WHERE account_number IS NOT NULL AND account_number <> ''",
        "SELECT CONCAT(payout_account_number, '/', payout_bank_code) AS account FROM gopay_settings WHERE payout_account_number IS NOT NULL AND payout_account_number <> ''",
    ];

