        'wipe', 'token', 'password', 'blob_pdf', 'blob_text',
    ];

    /** Odvozené klíče a symboly — potřebují hotové mapování ze strukturovaného průchodu. */
    public const PHASE_DERIVED = ['account_key', 'symbol'];

    /** Volné texty a JSON — potřebují úplný slovník. */
    public const PHASE_TEXT = ['text', 'json'];

    /** @return list<string> */
    public static function knownStrategies(): array
    {
        return [...self::PHASE_STRUCTURED, ...self::PHASE_DERIVED, ...self::PHASE_TEXT, 'keep', 'sealed_companion'];
    }

    public static function isSealed(string $strategy): bool
    {
        return str_starts_with($strategy, 'sealed:');
    }

    /**
     * @return array{field:string, type_column:?string, hash:string, masked:?string, entity:string}
     */
    public static function parseSealed(string $strategy): array
    {
        $parts = explode(':', $strategy);
        if (count($parts) !== 5 || $parts[0] !== 'sealed') {
            throw new \InvalidArgumentException("Neplatná strategie šifrované hodnoty: {$strategy}");
        }
        $typeColumn = str_starts_with($parts[1], '@') ? substr($parts[1], 1) : null;

        return [
            'field' => $typeColumn === null ? $parts[1] : '',
            'type_column' => $typeColumn,
            'hash' => $parts[2],
            'masked' => $parts[3] === '-' ? null : $parts[3],
            'entity' => $parts[4],
        ];
    }
}
